let list = VirtualList::new(10_000, |index| Text::new(format!("Row {index}")))
    .key(|index| index as u64)
    .selection(chosen.binding())
    .height(320.0);
let mut ui = Ui::new(list, ravenrs_style::Theme::raven_dark());
ui.update();
```

